Promise.resolve(1)
  .then(
    () => {
      throw 2;
    },
    () => console.log(3),
  )
  .catch((n) => console.log(n));

Promise.reject(1)
  .then(
    () => console.log(0),
    (n) => console.log(n),
  )
  .catch(() => console.log(2));

Promise.resolve(1)
  .finally(() => 9)
  .then((n) => console.log(n));

Promise.resolve(1)
  .finally(() => {
    throw 4;
  })
  .then(
    (n) => console.log(n),
    (n) => console.log(n),
  );

Promise.resolve(1)
  .finally(() => Promise.reject(4))
  .then(
    () => console.log(1),
    (n) => console.log(n),
  );

Promise.resolve()
  .then(() => Promise.resolve(1))
  .then((n) => console.log(n));
Promise.resolve()
  .then(() => 2)
  .then((n) => console.log(n));

const thenable = {
  then(resolve) {
    resolve(7);
  },
};
Promise.resolve(thenable).then((n) => console.log(n));
console.log(8);

Promise.allSettled([
  Promise.resolve(1),
  Promise.reject(2),
]).then((xs) => {
  console.log(xs[0].status === 'fulfilled' ? 1 : 0);
  console.log(xs[1].status === 'rejected' ? 2 : 0);
});

Promise.any([
  Promise.reject(1),
  Promise.resolve(2),
  Promise.reject(3),
]).then((n) => console.log(n));

Promise.any([
  Promise.reject(1),
  Promise.reject(2),
]).catch((e) => console.log(e.errors.length));

Promise.resolve(6)
  .then(null)
  .then((n) => console.log(n));

async function f() {
  try {
    return Promise.reject(1);
  } catch {
    return 2;
  }
}
f().then(
  (n) => console.log(n),
  (n) => console.log(n),
);

async function f() {
  try {
    return await Promise.reject(1);
  } catch {
    return 2;
  }
}
f().then((n) => console.log(n));

const out = [];
[1, 2].forEach(async (id) => {
  await Promise.resolve();
  out.push(id);
});
console.log(out.length);

new Promise(() => {
  throw 5;
}).catch((n) => console.log(n));
